M = [
{"id":"sandalyenamaz","yol":["Namaz","Kaza ve hasta namazı"],"baslik":"Sandalyede namaz kılmak","ar":"الصلاة على الكرسي",
 "hanefi":"Ayakta durmaya ya da yere secde etmeye gücü yetmeyen hasta ve yaşlılar sandalyede oturarak namaz kılabilir. Ayakta durabilen fakat secde edemeyen kişinin oturarak ima ile kılması daha faziletlidir; kıyamı ayakta yapıp rükû ve secde için sandalyeye oturması da caizdir. Secde, rükûdan biraz daha eğilerek ima ile yapılır; önüne bir şey koyup üzerine secde etmek gerekmez. Ayakta durup yere secde edebilen kişinin farz namazı sandalyede kılması caiz değildir.",
 "mez":{"maliki":["Özre bağlı caiz","Kıyama gücü yeten ayakta kılar; secde edemeyen ima eder."],
        "safii":["Özre bağlı caiz","Gücü yettiği rüknü yerine getirir; yapamadığını ima ile yapar."],
        "hanbeli":["Özre bağlı caiz","Ayakta durabiliyorsa kıyamı ayakta yapar."]},
 "sebep":"Kıyamın amaç mı (müstakil rükün) yoksa secdeye vesile mi olduğu; secdeden aciz olandan kıyamın düşüp düşmediği.",
 "delil":[["hadis","İmrân b. Husayn hadisi",hadis("صل قائما فإن لم تستطع فقاعدا فإن لم تستطع فعلى جنب"),"Buhârî, Taksîrü’s-salât, 19: “Ayakta kıl; gücün yetmezse oturarak, yine yetmezse yan üstü yatarak.”"],
          ["ayet","Bakara 2:286","./#2-286","“Allah kimseye gücünün üstünde yük yüklemez.”"]],
 "usul":"Hanefîlere göre kıyam, secdeye ulaşmak için meşrudur; secdeden aciz olandan kıyam da düşer ve oturarak ima ile kılmak efdal olur."},
{"id":"yuksekenlem","yol":["Namaz","Vakitler ve şartlar"],"baslik":"Yatsı vakti oluşmayan yerler (yüksek enlem)","ar":"فاقد وقت العشاء",
 "hanefi":"Yazın şafağın kaybolmadığı kuzey bölgelerinde yatsı vaktinin alameti oluşmaz. Hanefî âlimlerinden bir kısmı bu durumda yatsının düştüğünü söylemiş, fetvada esas alınan görüş ise yatsının takdir edilerek kılınmasıdır. Diyanet İşleri Başkanlığı bu bölgeler için en yakın normal bölgenin vakitlerini veya belirli bir enleme göre hesaplanan vakitleri esas alan takvimler hazırlar. Oruçta da imsak ve iftar bu takdirle belirlenir.",
 "mez":{"maliki":["Takdir edilir","En yakın normal bölgeye göre vakit belirlenir."],
        "safii":["Takdir edilir","Vakti oluşan en yakın bölgenin vakti esas alınır."],
        "hanbeli":["Takdir edilir","Deccâl hadisine kıyasla takdir yapılır."]},
 "sebep":"Vaktin namazın sebebi mi yoksa yalnız şartı mı olduğu; sebep bulunmayınca yükümlülüğün düşüp düşmeyeceği.",
 "delil":[["hadis","Deccâl günlerinin takdiri",hadis("اقدروا له قدره"),"Müslim, Fiten, 110: Bir yıl kadar uzun günde namazların “miktarınca takdir edin” buyrulmuştur."]],
 "usul":"Namazlar beş vakit olarak farzdır; alametin bulunmaması farzı düşürmez, takdir (kıyas ve tahmin) yoluna gidilir."},
{"id":"ucakoruc","yol":["Oruç","Oruç"],"baslik":"Uçakta oruç ve iftar vakti","ar":"الصيام في الطائرة",
 "hanefi":"Oruçlu kişi, bulunduğu yerde güneşin batışını görünce iftar eder. Uçakta yükseklik sebebiyle güneş yerdekinden daha geç batar; yolcu uçağın bulunduğu konumda güneşin battığını görmedikçe iftar etmez. Batıya doğru uçuşta gün uzayabilir; bu zorluk, yolculuk ruhsatından yararlanıp orucu sonra kaza etmeyi caiz kılar. Uçağın kalktığı ya da ineceği şehrin takvimiyle iftar edilmez.",
 "mez":{"maliki":["Aynı","Güneşin batışı yolcunun bulunduğu yere göre belirlenir."],
        "safii":["Aynı","Uçaktaki kişi güneşi görüyorsa oruç devam eder."],
        "hanbeli":["Aynı","Ruhsat olarak yolcu orucu bozabilir, sonra kaza eder."]},
 "sebep":"Günümüze özgü bir meseledir; mezheplerin genel ilkelerinden (vaktin yolcunun bulunduğu yere göre belirlenmesi) çıkarılmıştır.",
 "delil":[["hadis","“Gece buradan gelip gündüz buradan gidince ve güneş batınca oruçlu iftar eder.”",hadis("إذا أقبل الليل من ها هنا وأدبر النهار من ها هنا وغربت الشمس فقد أفطر الصائم"),"Buhârî, Savm, 43; Müslim, Sıyâm, 51."],
          ["ayet","Bakara 2:184","./#2-184","“…Sizden kim hasta veya yolculukta olursa tutamadığı günler sayısınca başka günlerde tutar.”"]],
 "usul":"Hüküm, alamete (güneşin batışına) bağlıdır; alamet kişinin bulunduğu yerde gerçekleşmedikçe hüküm de gerçekleşmez."},
{"id":"internetnikah","yol":["Nikâh ve talâk","Nikâh"],"baslik":"Telefon veya internet üzerinden nikâh","ar":"عقد النكاح عبر الهاتف والإنترنت",
 "hanefi":"Hanefîlere göre nikâhta icap ve kabulün aynı mecliste olması ve iki şahidin her iki tarafın sözlerini birlikte işitmesi şarttır. Telefon veya görüntülü görüşmede taraflar ve şahitler farklı yerlerde olduğundan meclis birliği tam gerçekleşmez; sahte kimlik ihtimali de bulunur. Bu sebeple taraflardan birinin nikâh mecliste hazır bulunan birine vekâlet vermesi ve nikâhın vekil aracılığıyla şahitler huzurunda kıyılması yolu tercih edilmelidir.",
 "mez":{"maliki":["Vekâlet tavsiye edilir","Velinin ve şahitlerin bulunması gibi şartlar ihtiyatı gerektirir."],
        "safii":["Caiz görülmez (çoğunluk)","Şahitlerin akdi bizzat işitip görmesi şarttır; vekâlet yolu gösterilir."],
        "hanbeli":["Vekâlet tavsiye edilir","Meclis birliği ve şahitlerin durumu sebebiyle ihtiyat esastır."]},
 "sebep":"Meclis birliğinin hakikî (aynı yer) mi yoksa hükmî (aynı anda iletişim) mi olduğu; şahitlerin tarafları tanıma ve işitme şartı.",
 "delil":[["hadis","“Velisiz ve iki adil şahitsiz nikâh olmaz.”",hadis("لا نكاح إلا بولي وشاهدي عدل"),"Dârekutnî, Nikâh; Beyhakî, es-Sünenü’l-kübrâ (Hanefîler velî şartını ergin kadın için aramaz)."]],
 "usul":"Nikâhta ihtiyat esastır (el-asl fi’l-ebda‘ et-tahrîm); şüpheli yol yerine şüphesiz yol (vekâlet) tercih edilir."},
{"id":"resminikah","yol":["Nikâh ve talâk","Nikâh"],"baslik":"Resmî nikâh ile dinî nikâh","ar":"العقد المدني والعقد الشرعي",
 "hanefi":"Nikâhın dinen geçerli olması için taraflar arasında evlenme engeli bulunmaması, icap-kabul ve iki şahit yeterlidir. Belediyede yapılan resmî nikâh da bu şartları taşıdığından dinen geçerli bir nikâhtır. Ancak resmî nikâh kılınmadan sadece imam nikâhıyla yetinmek kadının ve çocukların hukukunu korumasız bırakır; bu sebeple Diyanet İşleri Başkanlığı dinî nikâhın resmî nikâhtan sonra kıyılmasını esas alır. Ülkenin kanunlarına uymak ve hakları korumak dinen de gereklidir.",
 "mez":{"maliki":["Şartları taşıyorsa geçerli","Mâlikîlerde velî şartı ve ilânın yapılması aranır."],
        "safii":["Şartları taşıyorsa geçerli","Velînin akdi yapması şartı aranır."],
        "hanbeli":["Şartları taşıyorsa geçerli","Velî ve şahit şartı aranır."]},
 "sebep":"Nikâhın geçerlilik şartlarının resmî akitte bulunup bulunmadığı (özellikle velî şartı) ve hakların korunması (maslahat).",
 "delil":[["ayet","Nisâ 4:21","./#4-21","“…Onlar sizden sağlam bir söz (mîsâk-ı galîz) almışlardır.”"],
          ["ayet","Nisâ 4:59","./#4-59","“…Allah’a itaat edin, Peygamber’e ve sizden olan yetki sahiplerine itaat edin.”"]],
 "usul":"Mubah alanda devletin hakları korumak için koyduğu düzenlemelere uymak, maslahat ve “zarar giderilir” kaidesi gereğidir."},
]
